"""Rewrite the autogenerated initial-schema revision so PostgreSQL accepts it.

``alembic revision --autogenerate`` (run against SQLite) emitted 30
``op.create_table`` calls alphabetically with all 60 foreign keys inlined.
SQLite does not resolve foreign-key targets while parsing DDL, so it accepts
that. PostgreSQL validates them and aborts:

    psycopg2.errors.UndefinedTable: relation "users" does not exist

Reordering alone cannot fix it: this schema has genuine cycles
(``incidents`` -> ``optimization_plans`` -> ``optimization_requests`` ->
``incidents``, plus ``incidents`` <-> ``simulation_runs``), so some constraints
can only exist once both endpoints do.

The rewrite produces the shape Alembic itself emits for cyclic schemas:

  upgrade()    create every table in dependency order *without* inline foreign
               keys, then add all 60 with ``create_foreign_key``
  downgrade()  drop the constraints first, then indexes and tables in the exact
               reverse order

Every column, primary key, unique constraint, check constraint, index and
``ondelete`` behaviour is carried over unchanged; each foreign key gains a
deterministic name so both directions stay symmetric. Parsing uses :mod:`ast`,
so quoting and line wrapping in the revision cannot confuse it.

Usage:
    python scripts/sort_migration.py backend/migrations/versions/<rev>.py
    python scripts/sort_migration.py backend/migrations/versions/<rev>.py --check
"""

from __future__ import annotations

import ast
import sys
from pathlib import Path

_HELPERS = '''def _add_foreign_key(name, table, target, columns, remote_columns, ondelete=None):
    """Add one foreign key, portably.

    PostgreSQL can ALTER a table to add a constraint; SQLite cannot, so there the
    constraint is added by rebuild-and-copy (Alembic's batch mode).
    """
    if op.get_bind().dialect.name == "sqlite":
        with op.batch_alter_table(table, recreate="always") as batch:
            batch.create_foreign_key(name, target, columns, remote_columns, ondelete=ondelete)
    else:
        op.create_foreign_key(name, table, target, columns, remote_columns, ondelete=ondelete)


def _drop_foreign_key(name, table):
    """Mirror of _add_foreign_key.

    On SQLite the constraint disappears with its table, and tables are dropped in
    reverse creation order, so nothing is ever left referencing a dropped table.
    """
    if op.get_bind().dialect.name != "sqlite":
        op.drop_constraint(name, table, type_="foreignkey")
'''


def call_attr(node: ast.AST) -> str | None:
    """The attribute name of an ``op.<name>(...)`` statement node."""
    if not isinstance(node, ast.Expr) or not isinstance(node.value, ast.Call):
        return None
    func = node.value.func
    if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == "op":
        return func.attr
    return None


def is_fk_constraint(node: ast.AST) -> bool:
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "ForeignKeyConstraint"
    )


def literal(node: ast.AST) -> object:
    try:
        return ast.literal_eval(node)
    except (ValueError, SyntaxError):
        return None


class Revision:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.text = path.read_text()
        self.lines = self.text.splitlines(keepends=True)
        self.tree = ast.parse(self.text)

    def function(self, name: str) -> ast.FunctionDef:
        for node in self.tree.body:
            if isinstance(node, ast.FunctionDef) and node.name == name:
                return node
        raise SystemExit(f"{self.path.name} has no {name}() function.")

    def src(self, start: int, end: int) -> str:
        """Source lines for a 1-based inclusive span."""
        return "".join(self.lines[start - 1 : end])

    # -- extraction ------------------------------------------------------
    def tables(self) -> list[dict]:
        """Every op.create_table call, with its foreign keys pulled out."""
        found = []
        for node in self.function("upgrade").body:
            if call_attr(node) != "create_table":
                continue
            call = node.value
            name = literal(call.args[0])
            if not isinstance(name, str):
                raise SystemExit(f"Unsupported create_table argument on line {node.lineno}")

            kept_args = [arg for arg in call.args if not is_fk_constraint(arg)]
            kept_keywords = [kw for kw in call.keywords if not is_fk_constraint(kw.value)]
            if kept_args != list(call.args) or kept_keywords != list(call.keywords):
                # Re-render without the constraints; ast.unparse keeps every
                # retained column/constraint definition byte-for-byte equivalent.
                stripped = ast.Call(func=call.func, args=kept_args, keywords=kept_keywords)
                call_src = "    " + ast.unparse(stripped).replace("\n", "\n    ") + "\n"
            else:
                call_src = self.src(node.lineno, node.end_lineno)

            fks = []
            for arg in call.args:
                if is_fk_constraint(arg):
                    fks.append(_fk(name, arg))
            for kw in call.keywords:
                if is_fk_constraint(kw.value):
                    fks.append(_fk(name, kw.value))
            found.append({"name": name, "sql": call_src, "fks": fks})
        if not found:
            raise SystemExit("No op.create_table statements found — nothing to do.")
        return found

    # -- ordering --------------------------------------------------------
    @staticmethod
    def order(tables: list[dict]) -> list[str]:
        """Creation order, cutting only the edges that form cycles.

        Those edges are precisely the ones added later by create_foreign_key, so
        cutting them here is the same decision Alembic makes for cyclic schemas.
        """
        names = [t["name"] for t in tables]
        deps = {t["name"]: {fk["target"] for fk in t["fks"] if fk["target"] != t["name"]} for t in tables}
        unknown = {r for refs in deps.values() for r in refs} - set(names)
        if unknown:
            raise SystemExit(f"Foreign keys point at tables not created here: {', '.join(sorted(unknown))}")

        index: dict[str, int] = {}
        low: dict[str, int] = {}
        stack: list[str] = []
        on_stack: set[str] = set()
        components: list[list[str]] = []
        counter = [0]

        def strongconnect(node: str) -> None:
            index[node] = low[node] = counter[0]
            counter[0] += 1
            stack.append(node)
            on_stack.add(node)
            for dep in sorted(deps[node]):
                if dep not in index:
                    strongconnect(dep)
                    low[node] = min(low[node], low[dep])
                elif dep in on_stack:
                    low[node] = min(low[node], index[dep])
            if low[node] == index[node]:
                component = []
                while True:
                    member = stack.pop()
                    on_stack.discard(member)
                    component.append(member)
                    if member == node:
                        break
                components.append(component)

        for name in names:
            if name not in index:
                strongconnect(name)

        deferred = {
            (name, dep)
            for component in components
            if len(component) > 1
            for name in component
            for dep in deps[name]
            if dep in component
        }

        remaining = {n: {d for d in deps[n] if (n, d) not in deferred} for n in names}
        ordered: list[str] = []
        while remaining:
            ready = sorted(n for n, refs in remaining.items() if not (refs & set(remaining)))
            if not ready:  # pragma: no cover - guards against a logic error
                raise SystemExit("Ordering failed after cutting cycle edges.")
            for name in ready:
                ordered.append(name)
                del remaining[name]
        return ordered


def _fk(table: str, call: ast.Call) -> dict:
    local = literal(call.args[0]) if call.args else None
    remote = literal(call.args[1]) if len(call.args) > 1 else None
    if not local or not remote:
        raise SystemExit(f"Unsupported ForeignKeyConstraint in {table}: two list literals required.")
    ondelete = None
    for kw in call.keywords:
        if kw.arg == "ondelete":
            ondelete = literal(kw.value)
    column = str(local[0])
    return {
        "table": table,
        "columns": list(local),
        "remote_columns": [str(r).split(".")[-1] for r in remote],
        "target": str(remote[0]).split(".")[0],
        "ondelete": ondelete,
        "name": f"fk_{table}_{column}"[:60],
    }


def _split_top_level(text: str) -> list[str]:
    """Split on commas that are not nested in (), [] or {}."""
    parts, depth, current = [], 0, []
    for char in text:
        if char in "([{":
            depth += 1
        elif char in ")]}":
            depth -= 1
        if char == "," and depth == 0:
            parts.append("".join(current))
            current = []
        else:
            current.append(char)
    if current:
        parts.append("".join(current))
    return parts


def _drop_index(statement: str) -> str:
    """Turn 'op.create_index(<name>, <table>, <cols>, ...)' into a drop."""
    body = statement.strip().removeprefix("op.create_index(").removesuffix(")")
    name, table = _split_top_level(body)[0].strip(), _split_top_level(body)[1].strip()
    return f"    op.drop_index({name}, table_name={table})\n"


def rewrite(revision: Revision) -> tuple[str, list[str]]:
    tables = revision.tables()
    ordered = revision.order(tables)
    by_name = {t["name"]: t for t in tables}

    # Indexes belong to their table: keeping them adjacent means the mirror image
    # drops each index before the table it sits on.
    indexes: dict[str, list[str]] = {name: [] for name in ordered}
    for node in revision.function("upgrade").body:
        if call_attr(node) != "create_index":
            continue
        args = node.value.args
        table = literal(args[1]) if len(args) > 1 else None
        if isinstance(table, str) and table in indexes:
            indexes[table].append(revision.src(node.lineno, node.end_lineno))

    upgrade: list[str] = []
    deferred: list[dict] = []
    for name in ordered:
        upgrade.append(by_name[name]["sql"])
        upgrade.extend(indexes[name])
        deferred.extend(by_name[name]["fks"])

    upgrade.append(
        "\n    # Foreign keys are added only after every table exists: PostgreSQL\n"
        "    # validates the referenced table at DDL time and this schema contains\n"
        "    # circular references (incidents <-> plans <-> runs), so they cannot be\n"
        "    # declared inline in an order that works everywhere.\n"
    )
    for fk in deferred:
        ondelete = f", ondelete={fk['ondelete']!r}" if fk["ondelete"] else ""
        upgrade.append(
            f"    _add_foreign_key({fk['name']!r}, {fk['table']!r}, {fk['target']!r}, "
            f"{fk['columns']!r}, {fk['remote_columns']!r}{ondelete})\n"
        )

    downgrade = [
        f"    _drop_foreign_key({fk['name']!r}, {fk['table']!r})\n" for fk in reversed(deferred)
    ]

    drop_tables: dict[str, list[str]] = {name: [] for name in ordered}
    for node in revision.function("downgrade").body:
        if call_attr(node) == "drop_table":
            table = literal(node.value.args[0])
            if table in drop_tables:
                drop_tables[table].append(revision.src(node.lineno, node.end_lineno))

    tail: list[str] = []
    for name in reversed(ordered):
        tail.extend(_drop_index(s.strip()) for s in reversed(indexes[name]))
        tail.extend(drop_tables[name] or [f"    op.drop_table({name!r})\n"])

    upgrade_fn = revision.function("upgrade")
    downgrade_fn = revision.function("downgrade")
    banner = "    # ### commands auto generated by Alembic - please adjust! ###\n"
    text = (
        "".join(revision.lines[: upgrade_fn.lineno - 1]).rstrip("\n")
        + "\n"
        + _HELPERS
        + "\n\ndef upgrade() -> None:\n"
        + banner
        + "".join(upgrade)
        + "\n    # ### end Alembic commands ###\n"
        + "".join(revision.lines[upgrade_fn.end_lineno : downgrade_fn.body[0].lineno - 1])
        + banner
        + "".join(downgrade)
        + "".join(tail)
        + "\n    # ### end Alembic commands ###\n"
    )
    return text, ordered


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print("usage: python scripts/sort_migration.py <revision.py> [--check]")
        return 2
    revision = Revision(Path(argv[1]))
    text, ordered = rewrite(revision)
    if "--check" in argv[2:]:
        same = text == revision.text
        print("revision is PostgreSQL-portable." if same else "revision needs rewriting.")
        return 0 if same else 1
    revision.path.write_text(text)
    print(f"rewrote {revision.path.name}: {len(ordered)} tables, deferred foreign keys")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
